"""AudioSource data model for audio file metadata."""

from pathlib import Path

from pydantic import BaseModel, Field, field_validator


class AudioSource(BaseModel):
    """Represents an audio recording file for one Aliyah.

    Attributes:
        file_path: Absolute path to audio file
        format: File extension (e.g., "mp4", "mp3", "wav")
        duration_seconds: Total audio duration
        sample_rate: Audio sample rate in Hz (e.g., 44100, 48000)
        channels: Number of audio channels (1 for mono, 2 for stereo)
        attribution: Source attribution (e.g., reader's name)
        parasha_name: Extracted from filename
        aliyah_name: Extracted from filename
    """

    file_path: Path = Field(..., description="Absolute path to audio file")
    format: str = Field(..., min_length=1, description="File extension")
    duration_seconds: float = Field(..., gt=0.0, description="Total audio duration")
    sample_rate: int = Field(
        ..., ge=16000, le=48000, description="Audio sample rate in Hz"
    )
    channels: int = Field(..., ge=1, le=2, description="Number of audio channels")
    attribution: str = Field(default="", description="Source attribution")
    parasha_name: str = Field(..., min_length=1, description="Extracted Parasha name")
    aliyah_name: str = Field(..., min_length=1, description="Extracted Aliyah name")

    @field_validator("format")
    @classmethod
    def validate_format(cls, v: str) -> str:
        """Validate audio format is supported."""
        valid_formats = {"mp3", "mp4", "wav"}
        if v.lower() not in valid_formats:
            raise ValueError(
                f"Invalid audio format: {v}. Must be one of: {', '.join(sorted(valid_formats))}"
            )
        return v.lower()

    @field_validator("file_path")
    @classmethod
    def validate_file_exists(cls, v: Path) -> Path:
        """Validate audio file exists."""
        if not v.exists():
            raise ValueError(f"Audio file does not exist: {v}")
        if not v.is_file():
            raise ValueError(f"Path is not a file: {v}")
        return v

    @property
    def is_mono(self) -> bool:
        """Check if audio is mono (single channel)."""
        return self.channels == 1

    @property
    def file_size_mb(self) -> float:
        """Get file size in megabytes."""
        return self.file_path.stat().st_size / (1024 * 1024)

    def __str__(self) -> str:
        """Return string representation of the AudioSource."""
        return (
            f"{self.parasha_name}/{self.aliyah_name}.{self.format}: "
            f"{self.duration_seconds:.1f}s, {self.sample_rate}Hz, {self.channels}ch"
        )
